	/**
	 * Register admin menu and hooks.
	 */
	public static function init() {
		register_activation_hook( __FILE__, array( __CLASS__, 'on_activate' ) );
		add_action( 'admin_menu', array( __CLASS__, 'add_admin_menu' ) );
		add_action( 'init', array( __CLASS, 'add_shortcode' ) );

		// Conditional hooks based on enabled events.
		$opts = get_option( self::OPTION_NAME );
		$ev   = $opts['events'] ?? $default['events'];

		// Core WP events (always enabled for backwards compatibility).
		add_action( 'comment_post', array( __CLASS, 'forward_comment' ), 10, 1 );
		add_action( 'publish_post', array( __CLASS, 'forward_post_publish' ), 10, 1 );
		add_action( 'wp_insert_user', array( __CLASS, 'forward_user_create' ), 10, 1 );
		add_action( 'transition_post_status', array( __CLASS, 'forward_post_status_change' ), 10, 3 );

		// WooCommerce events (only if WooCommerce is active and enabled).
		if ( function_exists( 'wc' ) && $ev['forward_order_created'] ) {
			add_action( 'woocommerce_order_created', array( __CLASS, 'forward_order_created' ), 20, 1 );
		}
		if ( function_exists( 'wc' ) && $ev['forward_order_status'] ) {
			add_action( 'woocommerce_order_status_changed', array( __CLASS, 'forward_order_status_changed' ), 20, 3 );
		}
		if ( function_exists( 'wc' ) && $ev['forward_product_view'] ) {
			add_action( 'woocommerce_product_viewed', array( __CLASS, 'forward_product_viewed' ), 20, 1 );
		}
		// Page view forwarding (simple implementation – can be extended).
		if ( $ev['forward_page_view'] ) {
			add_action( 'template_redirect', array( __CLASS, 'forward_page_view' ) );
		}

		// Front-end support chat.
		add_shortcode( 'customer_chat', array( __CLASS, 'customer_chat_shortcode' ) );
		add_action( 'wp_ajax_forward_message', array( __CLASS, 'ajax_forward_message' ) );
		add_action( 'wp_ajax_send_reply', array( __CLASS, 'ajax_send_reply' ) );
	}

	/**
	 * Ensure defaults on every load.
	 */
	public static function ensure_defaults() {
		$opts = get_option( self::OPTION_NAME );
		$default = array(
			'telegram_bot_token'       => '',
			'telegram_chat_id'         => '',
			'bale_bot_token'           => '',
			'bale_chat_id'             => '',
			'rocketchat_url'           => 'https://chat.example.com/api',
			'rocketchat_user'          => '',
			'rocketchat_token'         => '',
			'events'                   => array(
				'forward_comment'       => true,
				'forward_post_publish'  => true,
				'forward_user_create'   => true,
				'forward_order_created' => false,
				'forward_order_status'  => false,
				'forward_product_view'  => false,
				'forward_page_view'     => false,
			),
		);
		foreach ( $default as $k => $v ) {
			if ( ! array_key_exists( $k, $opts ) ) {
				$opts[ $k ] = $v;
			}
		}
		// Merge events array safely.
		if ( ! isset( $opts['events'] ) || ! is_array( $opts['events'] ) ) {
			$opts['events'] = $default['events'];
		} else {
			$opts['events'] = array_merge( $default['events'], $opts['events'] );
		}
		update_option( self::OPTION_NAME, $opts );
	}

