	/**
	 * Send the given message to all configured messengers.
	 */
	public static function send_to_messengers( $message ) {
		$opts = get_option( self::OPTION_NAME );

		// Telegram
		if ( ! empty( $opts['telegram_bot_token'] ) && ! empty( $opts['telegram_chat_id'] ) ) {
			self::telegram_send( $opts['telegram_bot_token'], $opts['telegram_chat_id'], $message );
		}

		// Bale
		if ( ! empty( $opts['bale_bot_token'] ) && ! empty( $opts['bale_chat_id'] ) ) {
			self::bale_send( $opts['bale_bot_token'], $opts['bale_chat_id'], $message );
		}

		// Rocket.Chat
		if ( ! empty( $opts['rocketchat_url'] ) && ! empty( $opts['rocketchat_token'] ) ) {
			self::rocketchat_send( $opts['rocketchat_url'], $opts['rocketchat_token'], $message );
		}
	}

	/**
	 * Send message via Telegram Bot API.
	 */
	private static function telegram_send( $bot_token, $chat_id, $text ) {
		$url = "https://api.telegram.org/bot{$bot_token}/sendMessage";
		$args = array(
			'headers' => array( 'Content-Type: application/json' ),
			'server'  => parse_url( $url, PHP_URL_HOST ),
			'body'    => json_encode( array( 'chat_id' => $chat_id, 'text' => $text ) ),
			'timeout' => 30,
		);
		$response = wp_remote_post( $url, $args );
		if ( is_wp_error( $response ) ) {
			error_log( 'Telegram error: ' . $response->get_error_message() );
		}
	}

	/**
	 * Send message via Bale Bot API.
	 */
	private static function bale_send( $bot_token, $chat_id, $text ) {
		$url = "https://api.bale.ai/bot{$bot_token}/sendMessage";
		$args = array(
			'headers' => array( 'Content-Type: application/json' ),
			'body'    => json_encode( array( 'chat_id' => $chat_id, 'text' => $text ) ),
			'timeout' => 30,
		);
		$response = wp_remote_post( $url, $args );
		if ( is_wp_error( $response ) ) {
			error_log( 'Bale error: ' . $response->get_error_message() );
		}
	}

	/**
	 * Send message to Rocket.Chat via its chat.post message API.
	 */
	private static function rocketchat_send( $url, $token, $text ) {
		$post_url = rtrim( $url, '/' ) . '/chat.postMessage';
		$args = array(
			'headers' => array(
				'Content-Type: application/json',
				'Authorization: Bearer ' . $token,
			),
			'body'    => json_encode( array( 'roomId' => 'YOUR_ROOM_ID', 'text' => $text ) ),
			'timeout' => 30,
		);
		$response = wp_remote_post( $post_url, $args );
		if ( is_wp_error( $response ) ) {
			error_log( 'Rocket.Chat error: ' . $response->get_error_message() );
		}
	}

