				<span id="wp-chat-close" style="cursor:pointer; float:right; font-size:1.2rem;">×</span>
			</div>
			<div id="wp-chat-messages" style="height: 300px; overflow-y: auto; padding: 10px; font-size: 0.9rem;">
				<?php // Messages will be loaded via AJAX; here we just show a placeholder. ?>
				<p class="empty"><?php _e( 'Start a conversation...', 'wp-messenger-forward' ); ?></p>
			</div>
			<div id="wp-chat-input" style="padding: 10px; border-top: 1px solid #ddd; display: none;">
				<input type="text" id="wp-chat-message" style="width: 80%; padding: 6px; border: 1px solid #ccc; border-radius: 4px;">
				<button id="wp-chat-send" style="margin-left: 10px; padding: 0 12px; background: #2962ff; color: #fff; border: none; border-radius: 4px; cursor: pointer;">Send</button>
			</div>
		</div>

		<script type="text/javascript">
			jQuery(function($){
				var $chat = $('#wp-messenger-chat');
				var $messages = $('#wp-chat-messages');
				var $input = $('#wp-chat-message');
				var $send   = $('#wp-chat-send');
				var $close  = $('#wp-chat-close');

				// Toggle chat box
				$chat.on('click', function(){
					$chat.toggleClass('expanded');
					if ( $chat.hasClass('expanded') ) {
						$input.parent().show();
					} else {
						$input.parent().hide();
					}
				});
				$close.on('click', function(){
					$chat.removeClass('expanded');
					$input.parent().hide();
				});

				// Send message
				$.send_chat_message = function(text){
					$.ajax({
						url: wpajax_obj.ajax_url,
						type: 'POST',
						data: {
							action: 'forward_message',
							message: text,
							nonce: wpajax_obj.nonce
						},
						success: function(res){
							if ( res.success ) {
								$messages.append('<p><strong>You:</strong> ' + text + '</p>');
								$messages.scrollTop( $messages[0].scrollHeight );
								$input.val('').focus();
							}
						},
						error: function(){
							alert('Error sending message.');
						}
					});
				};

				$send.on('click', function(){
					var txt = $input.val().trim();
					if ( txt ) {
						$.send_chat_message( txt );
					}
				});
				$input.on('keypress', function(e){
					if ( e.which === 13 ) { // Enter
						$( '.wp-chat-send' ).trigger('click');
					}
				});

				// Load existing messages (optional)
				$.ajax({
					url: wpajax_obj.ajax_url,
					type: 'POST',
					data: {
						action: 'load_chat_messages',
						nonce: wpajax_obj.nonce
					},
					success: function(res){
						if ( res.messages ) {
							$.each(res.messages, function(i, m){
								$messages.append('<p><strong>' + m.sender + ':</strong> ' + m.text + '</p>');
							});
							$messages.scrollTop( $messages[0].scrollHeight );
						}
					}
				});
			});
		</script>
