		$content = ob_get_clean();
		return $content;
	}

	/**
	 * AJAX handler: forward a customer message to all messengers.
	 */
	public static function ajax_forward_message() {
		check_ajax_referer( 'forward_message_nonce', 'nonce' );
		if ( ! current_user_can( 'edit_posts' ) ) {
			wp_send_json_error( 'Unauthorized' );
		}
		$message = isset( $_POST['message'] ) ? sanitize_text_field( $_POST['message'] ) : '';
		if ( ! $message ) {
			wp_send_json_error( 'Empty message' );
		}
		self::send_to_messengers( $message );
		wp_send_json_success( array( 'status' => 'forwarded' ) );
	}

	/**
	 * AJAX handler: send a reply back to the customer via the messengers.
	 * Uses the same chat IDs that are configured in the settings, so the reply
	 * appears in the same conversation thread where the original message arrived.
	 */
	public static function ajax_send_reply() {
		check_ajax_referer( 'forward_message_nonce', 'nonce' );
		if ( ! current_user_can( 'edit_posts' ) ) {
			wp_send_json_error( 'Unauthorized' );
		}
		$reply   = isset( $_POST['reply'] ) ? sanitize_text_field( $_POST['reply'] ) : '';
		if ( ! $reply ) {
			wp_send_json_error( 'Empty reply' );
		}
		// Prefix the reply so it's clear it's a response.
		$formatted = sprintf(
			"💬 Reply:\n%s",
			$reply
		);
		self::send_to_messengers( $formatted );
		wp_send_json_success( array( 'status' => 'replied' ) );
	}
}

// Ensure defaults on every load.
WP_Messenger_Forward::ensure_defaults();

// Initialize the plugin hooks.
WP_Messenger_Forward::init();
